mission.script:
// The wave for round r: 1-3, then 2-5 from round 4, 4-7 from round 7,
// then both ends x1.5 (rounded up) every 5 rounds.
fn wave_size(r) {
  let lo = 1;
  let hi = 3;
  if r >= 4 { lo = 2; hi = 5; }
  if r >= 7 {
    lo = 4; hi = 7;
    let steps = (r - 7) / 5;
    for i in 0..steps {
      lo = (lo.to_float() * 1.5).ceiling().to_int();
      hi = (hi.to_float() * 1.5).ceiling().to_int();
    }
  }
  rand(lo, hi)
}

// Who comes: tougher enemies join as the rounds go on.
fn pick_enemy(r) {
  let k = rand(1, 12);
  if r >= 12 && k == 1 { return ["symb_amalgam", "Amalgam"]; }
  if r >= 8 && k == 2 { return ["symb_puppeteer", "Puppeteer"]; }
  if k <= 6 { return ["symb_crawler", "Crawler"]; }
  ["symb_host", "Host"]
}

fn spawn_wave() {
  let n = wave_size(round);
  let room = 40 - alive_count("enemy");
  if n > room { n = room; }
  let pts = [[2, 0], [2, 33], [0, 2], [33, 2], [5, 0], [5, 33], [0, 5], [33, 5], [8, 0], [8, 33], [0, 8], [33, 8], [11, 0], [11, 33], [0, 11], [33, 11], [14, 0], [14, 33], [0, 14], [33, 14], [17, 0], [17, 33], [0, 17], [33, 17], [20, 0], [20, 33], [0, 20], [33, 20], [23, 0], [23, 33], [0, 23], [33, 23], [26, 0], [26, 33], [0, 26], [33, 26], [29, 0], [29, 33], [0, 29], [33, 29]];
  for i in 0..n {
    let p = pts[rand(0, pts.len() - 1)];
    let e = pick_enemy(round);
    spawn_unit("enemy", e[0], e[1], p[0], p[1]);
  }
  if n > 0 { message("Round " + round + ": " + n + " more coming."); }
  ai_goal("enemy", 17, 17);
}

message("The station atrium. Something is moving in every vent.");
message("There's no winning here - hold out as long as you can. The waves grow every few rounds.");
objective("Hold out: round 1");
